    input  aresetn,
    input  x,
    output z
);
    reg [1:0] state, next_state;
    wire a = (state == 2'b00) & x;
    wire b = (state == 2'b01) & x;
    wire c = (state == 2'b10) & x;
    always @(*) begin
        next_state = state;
        case (state)
            2'b00: next_state = a ? 2'b01 : 2'b00;
            2'b01: next_state = b ? 2'b10 : 2'b00;
            2'b10: next_state = c ? 2'b10 : 2'b00;
        endcase
    end
    always @(posedge clk) begin
        if (!aresetn) state <= 2'b00;
        else state <= next_state;
    end
    assign z = (state == 2'b10) & x;
endmodule
